package com.sendw.mpos.imports.application;
import com.sendw.mpos.identity.application.*;
import com.sendw.mpos.shared.domain.*;
import com.sendw.mpos.shared.application.RequestDeduplicator;
import com.sendw.mpos.inventory.application.StockOperations;
import com.sendw.mpos.sales.application.SaleService;
import com.sendw.mpos.imports.domain.ImportRules;
import java.util.*;
import java.math.*;
import org.springframework.transaction.annotation.Transactional;
@org.springframework.stereotype.Service
public class ImportService {
 private final ImportRepository repository;private final StockOperations stock;private final IdentityService identity;private final SaleService sales;private final RequestDeduplicator dedupe;
 public ImportService(ImportRepository r,StockOperations s,IdentityService i,SaleService sales,RequestDeduplicator d){repository=r;stock=s;identity=i;this.sales=sales;dedupe=d;}
 private void permit(){Permissions.require("manage_imports");}
 private Map<String,Object> clean(Map<String,Object> row){var result=new LinkedHashMap<>(row);result.replaceAll((k,v)->v instanceof java.sql.Timestamp x?x.toInstant().toString():v instanceof java.sql.Date x?x.toString():v);return result;}
 private List<Map<String,Object>> cleanList(List<Map<String,Object>> rows){return rows.stream().map(this::clean).toList();}
 private long id(Object v){return ((Number)v).longValue();}
 private Map<String,Object> active(long id){var s=repository.shipment(id,true);if("cancelled".equals(s.get("status")))throw Requests.conflict("الشحنة ملغاة / Shipment cancelled");return s;}
 public Map<String,Object> lookups(){permit();return Map.of("data",repository.lookups());}
 public Map<String,Object> partners(){permit();return Map.of("data",repository.partners());}
 @Transactional public Map<String,Object> savePartner(Long id,Map<String,Object>b){permit();var f=new LinkedHashMap<String,Object>();for(String k:List.of("name","phone","email","address","kind"))f.put(k,Requests.text(b,k,k.equals("address")?500:k.equals("phone")?40:254,k.equals("name")||k.equals("kind")));if(!Set.of("shipping_agent","transport_agent").contains(f.get("kind")))throw Validation.invalid("Invalid partner type");String email=(String)f.get("email");if(!email.isBlank())com.sendw.mpos.messaging.application.MailService.email(email);long saved=repository.savePartner(id,f);return Map.of("data",repository.partner(saved));}
 public Map<String,Object> list(int page,String search){permit();if(page<1||search.length()>100)throw Validation.invalid("Invalid search");String pattern="%"+search.replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";return Map.of("data",cleanList(repository.list(page,pattern)),"total",repository.count(pattern));}
 public Map<String,Object> show(long id){permit();var data=clean(repository.shipment(id,false));var containers=repository.containers(id);var expenses=repository.expenses(id);data.put("containers",containers);data.put("actual_containers",containers.size());data.put("total_pieces",containers.stream().mapToLong(x->id(x.get("pieces"))).sum());data.put("remaining_pieces",containers.stream().mapToLong(x->id(x.get("remaining_pieces"))).sum());data.put("weight_kg",containers.stream().map(x->(BigDecimal)x.get("weight_kg")).reduce(BigDecimal.ZERO,BigDecimal::add));data.put("expenses_sar",expenses.stream().map(x->(BigDecimal)x.get("amount_sar")).reduce(BigDecimal.ZERO,BigDecimal::add));data.put("expenses",cleanList(expenses));data.put("files",cleanList(repository.files(id)));data.put("sales",cleanList(repository.sales(id)));return Map.of("data",data);}
 @Transactional public Map<String,Object> save(Long id,Map<String,Object>b,String key){permit();if(id==null)return dedupe.execute("import-shipments",key,b,()->persist(null,b));return persist(id,b);}
 private Map<String,Object> persist(Long id,Map<String,Object>b){if(id!=null){var old=active(id);if(!old.get("status").equals("draft"))throw Requests.conflict("بيانات الشحنة المستلمة مقفلة / Received shipment is locked");if(Validation.integer(Objects.toString(b.get("version"),"-1"))!=((Number)old.get("version")).intValue())throw Requests.conflict("Shipment changed; reload");}
  var f=new LinkedHashMap<String,Object>();f.put("date",Requests.date(b));f.put("booking_number",Requests.text(b,"booking_number",100,true));f.put("booking_confirmation_ref",Requests.text(b,"booking_confirmation_ref",255,false));f.put("notes",Requests.text(b,"notes",2000,false));f.put("warehouse_id",Requests.id(b,"warehouse_id"));f.put("expected_containers",Requests.choice(b,"expected_containers",1,200));
  for(String type:List.of("shipping_agent","transport_agent")){long partner=Requests.id(b,type+"_id");if(!repository.partner(partner).get("kind").equals(type))throw Validation.invalid("Incorrect agent type");f.put(type+"_id",partner);}
  var rows=Requests.items(b,"containers");var numbers=new HashSet<String>();for(var c:rows){String number=Requests.text(c,"container_number",30,true).toUpperCase(Locale.ROOT);if(!number.matches("[A-Z0-9 -]{1,30}")||!numbers.add(number))throw Validation.invalid("رقم كونتينر غير صالح أو مكرر / Invalid or duplicate container number");c.put("container_number",number);long product=Requests.id(c,"product_id");var p=repository.product(product);c.put("product_id",product);c.put("unit_id",p.get("product_unit"));c.put("unit_name",p.get("unit_name"));c.put("pieces",ImportRules.pieces(c.get("pieces")));var weight=Requests.nonnegative(c,"weight_kg",true);if(weight.signum()==0)throw Validation.invalid("Weight must be positive");c.put("weight_kg",weight);}
  long saved=repository.saveShipment(id,f,identity.current().id());repository.replaceContainers(saved,rows);return show(saved);
 }
 @Transactional public Map<String,Object> receive(long id){permit();var s=active(id);if(s.get("status").equals("received"))return show(id);var rows=repository.containers(id);if(rows.size()!=((Number)s.get("expected_containers")).intValue())throw Validation.invalid("أكمل بيانات العدد المتوقع للكونتينرات / Complete all expected containers");var deltas=new ArrayList<StockOperations.Delta>();for(var c:rows){var product=repository.product(id(c.get("product_id")));if(!product.get("product_unit").equals(c.get("unit_id")))throw Requests.conflict("Product unit changed; edit shipment before receipt");deltas.add(new StockOperations.Delta(id(s.get("warehouse_id")),id(c.get("product_id")),new BigDecimal(c.get("pieces").toString())));}stock.apply("IMPORT_RECEIPT",null,"Import shipment "+s.get("booking_number"),deltas);repository.receive(id);return show(id);}
 @Transactional public Map<String,Object> cancel(long id){permit();var s=repository.shipment(id,true);if(s.get("status").equals("cancelled"))return show(id);if(!s.get("status").equals("draft"))throw Requests.conflict("Only draft shipments can be cancelled");repository.cancel(id);return show(id);}
 private ImportRepository.ImportFile validate(String name,byte[] bytes){if(bytes==null||bytes.length==0||bytes.length>10485760)throw Validation.invalid("الملف مطلوب وبحد أقصى 10 MB / File required, maximum 10 MB");String mime;String start=new String(bytes,0,Math.min(bytes.length,8),java.nio.charset.StandardCharsets.ISO_8859_1);if(start.startsWith("%PDF-")&&new String(bytes,Math.max(0,bytes.length-2048),Math.min(bytes.length,2048),java.nio.charset.StandardCharsets.ISO_8859_1).contains("%%EOF"))mime="application/pdf";else if(bytes.length>8&&bytes[0]==(byte)0x89&&start.substring(1,4).equals("PNG")&&bytes[4]==13&&bytes[5]==10&&bytes[6]==26&&bytes[7]==10)mime="image/png";else if(bytes.length>3&&bytes[0]==(byte)0xff&&bytes[1]==(byte)0xd8&&bytes[2]==(byte)0xff)mime="image/jpeg";else throw Validation.invalid("يسمح بملفات PDF أو PNG أو JPEG فقط / PDF, PNG or JPEG required");String filename=Objects.toString(name,"attachment").replace('\\','/');filename=filename.substring(filename.lastIndexOf('/')+1).replaceAll("[\\p{Cntrl}]","");if(filename.isBlank())filename="attachment";if(filename.length()>180)filename=filename.substring(0,180);return new ImportRepository.ImportFile(filename,mime,bytes);}
 @Transactional public Map<String,Object> upload(long id,String kind,String name,byte[]bytes){permit();active(id);if(!Set.of("inspection_request","food_safety","origin_certificate","booking_confirmation","other").contains(kind))throw Validation.invalid("Invalid document type");repository.addFile(UUID.randomUUID(),id,null,kind,validate(name,bytes));return show(id);}
 public ImportRepository.ImportFile download(long id,UUID file){permit();return repository.file(id,file);}
 @Transactional public Map<String,Object> removeFile(long id,UUID file){permit();active(id);repository.removeFile(id,file);return show(id);}
 @Transactional public Map<String,Object> expense(long id,Map<String,Object>b,String name,byte[]bytes){permit();active(id);var f=new LinkedHashMap<String,Object>();String kind=Requests.text(b,"kind",30,true),currency=Requests.text(b,"currency",3,true);if(!Set.of("sea_freight","land_transport","clearance","goods","other").contains(kind)||!Set.of("SAR","USD","EGP").contains(currency))throw Validation.invalid("Invalid expense type or currency");var amount=Requests.nonnegative(b,"amount",true);if(amount.signum()==0)throw Validation.invalid("Amount must be positive");var rate=ImportRules.rate(b.get("rate_to_sar"),currency);f.putAll(Map.of("kind",kind,"currency",currency,"amount",amount,"rate_to_sar",rate,"amount_sar",ImportRules.sar(amount,rate),"date",Requests.date(b),"invoice_number",Requests.text(b,"invoice_number",100,true),"description",Requests.text(b,"description",1000,false)));var file=validate(name,bytes);long expense=repository.addExpense(id,f);repository.addFile(UUID.randomUUID(),id,expense,"expense_invoice",file);return show(id);}
 @Transactional public Map<String,Object> removeExpense(long id,long expense){permit();active(id);repository.removeExpense(id,expense);return show(id);}
 @Transactional public Map<String,Object> sell(long id,Map<String,Object>b,String key){permit();Permissions.require("manage_sale");return dedupe.execute("import-sales-"+id,key,b,()->sellNow(id,b));}
 private Map<String,Object> sellNow(long shipment,Map<String,Object>b){var s=active(shipment);if(!s.get("status").equals("received"))throw Validation.invalid("استلم الشحنة أولًا لإضافتها للمخزون / Receive the shipment first");var available=repository.containers(shipment);var byId=new HashMap<Long,Map<String,Object>>();for(var c:available)byId.put(id(c.get("id")),c);var allocations=Requests.items(b,"containers");String mode=Requests.text(b,"mode",20,true);if(!Set.of("shipment","container","pieces").contains(mode))throw Validation.invalid("Invalid sale mode");var seen=new HashSet<Long>();var grouped=new LinkedHashMap<Long,Map<String,Object>>();for(var a:allocations){long container=Requests.id(a,"container_id");var c=byId.get(container);if(c==null||!seen.add(container))throw Validation.invalid("Unknown or duplicate container");long pieces=ImportRules.pieces(a.get("pieces")),remaining=id(c.get("remaining_pieces"));if(pieces>remaining)throw Requests.conflict("الكمية تتجاوز المتبقي في الكونتينر / Quantity exceeds container balance");if(!mode.equals("pieces")&&pieces!=remaining)throw Validation.invalid("Select the full remaining container quantity");a.put("pieces",pieces);a.put("container_id",container);long product=id(c.get("product_id"));var price=Requests.nonnegative(a,"product_price",true);if(grouped.containsKey(product)){var line=grouped.get(product);if(((BigDecimal)line.get("product_price")).compareTo(price)!=0)throw Validation.invalid("Use one unit price per product within an invoice");line.put("quantity",((BigDecimal)line.get("quantity")).add(BigDecimal.valueOf(pieces)));}else{var line=new LinkedHashMap<String,Object>();line.putAll(Map.of("product_id",product,"sale_unit",c.get("unit_id"),"quantity",BigDecimal.valueOf(pieces),"product_price",price,"tax_type",1,"tax_value",0,"discount_type",2,"discount_value",0));grouped.put(product,line);}}
  if(mode.equals("container")&&allocations.size()!=1)throw Validation.invalid("Select one container");if(mode.equals("shipment")&&available.stream().anyMatch(c->id(c.get("remaining_pieces"))>0&&!seen.contains(id(c.get("id")))))throw Validation.invalid("Select all remaining containers");
  var sale=new LinkedHashMap<String,Object>();sale.putAll(Map.of("customer_id",Requests.id(b,"customer_id"),"warehouse_id",s.get("warehouse_id"),"date",Requests.date(b).toString(),"status",2,"sale_items",new ArrayList<>(grouped.values()),"discount",Requests.nonnegative(b,"discount",false),"tax_rate",Requests.rate(b,"tax_rate"),"shipping",BigDecimal.ZERO,"notes","Import shipment "+s.get("booking_number")));
  var result=sales.save(null,sale,"import-"+UUID.randomUUID());long saleId=id(((Map<?,?>)result.get("data")).get("id"));for(var a:allocations)repository.allocate(id(a.get("container_id")),saleId,id(a.get("pieces")));repository.setSaleCurrency(saleId,"SAR","ر.س");return sales.complete(saleId);
 }
}
